from itertools import product

def split(n,r):
 a=[round((n*x/sum(r))/16)*16 for x in r]; a[-1]+=n-sum(a); return a

def fix(a):
 a=a.copy()
 for i in range(len(a)-2,-1,-1):
  if a[i+1]<0:
   a[i]+=a[i+1];a[i+1]=0
 return a
for n,r in [(32,[3,3,3,1]),(48,[3,3,3,3,3,1]),(256,[2,2,4])]:
 a=split(n,r); print(n,r,a,fix(a))
c=0;neg=0
for d in range(2,6):
 for r in product(range(1,5),repeat=d):
  for n in range(129):
   a=split(n,r); b=fix(a); assert sum(b)==n and min(b)>=0
   if min(a)>=0: assert a==b
   neg+=min(a)<0;c+=1
print('checked',c,'cases;',neg,'negative partitions repaired')

